+ * 21 columns under test:
+ *   cargo_id, vessel_id, cargo_item_index, vessel_item_index,
+ *   score, reason, status, user_id,
+ *   cargo_type, load_port, discharge_port, laycan_start, laycan_end, vessel_dwt,
+ *   tce_usd_per_day, distance_nm, freight_rate_usd_per_mt, freight_rate_source,
+ *   fit_percent, fit_breakdown, worksheet_json
+ *
+ * Economics / breakeven / ballast are also spot-checked (both paths write them).
+ *
+ * analyzePairs is mocked with a realistic Match object (fitBreakdown + worksheet) so
+ * the test is deterministic and LLM-free.
+ */
+
+import Database from 'better-sqlite3';
+import migration032 from '@/lib/migrations/032-matches';
