+}
+
+function makeVessel(overrides: Partial<ParsedVessel> = {}): ParsedVessel {
+  return {
+    emailId: VESSEL_ID,
+    itemIndex: 0,
+    dwtSummer: { value: 32000, confidence: 'confirmed' },
+    vesselName: { value: 'M/V DEMO', confidence: 'confirmed' },
+    imo: null,
+    flag: null,
+    built: null,
+    classSociety: null,
+    pandi: null,
+    dwcc: null,
