+    openPosition: { value: 'Antwerp', confidence: 'confirmed' },
+    openDate: { value: '2026-06-28', confidence: 'confirmed' },
+    direction: null,
+    restrictions: [],
+    lastCargoes: null,
+    speedLaden: 13,
+    speedBallast: null,
+    consumption: 28,
+    deckCapacity: null,
+    specialFeatures: [],
+    ...overrides,
+  };
+}
+
+const stubFitBreakdown: FitBreakdown = {
+  components: [
+    { factor: 'utilisation', label: 'Utilisation', weight: 19, score: 16, rationale: 'Good util' },
+    { factor: 'timing', label: 'Timing', weight: 15, score: 13, rationale: 'Tight' },
+    { factor: 'ballast', label: 'Ballast', weight: 15, score: 10, rationale: 'Medium' },
+    { factor: 'classFit', label: 'Class fit', weight: 9, score: 9, rationale: 'Perfect' },
+    { factor: 'cargoType', label: 'Cargo type', weight: 6, score: 6, rationale: 'Grain ok' },
