+    utilisation: 0.78,
+    vesselDwt: 32000,
+    cargoWtMax: 25000,
+  },
+};
+
+const stubWorksheet = {
+  readiness: {
+    verdict: 'tight' as const,
+    gapDays: 3,
+    laycanStart: '2026-07-01',
+    laycanEnd: '2026-07-15',
