+    dwcc: null,
+  },
+  cargo: { weightMt: 25000, weightMtEffective: 25000, cargoType: 'grain', loadPort: 'Rotterdam', dischargePort: 'Singapore' },
+  hardFilters: { draft: { pass: true }, crane: { pass: true }, volume: { pass: true }, destDraft: { pass: true } },
