+function makeMatchObject() {
+  return {
+    cargoEmailId: CARGO_ID,
+    cargoItemIndex: 0,
+    vesselEmailId: VESSEL_ID,
+    vesselItemIndex: 0,
+    score: 82,
+    matchLevel: 'good' as const,
+    matchReasons: ['Good timing and fit'],
+    issues: [],
+    fitPercent: 85,
+    fitBreakdown: stubFitBreakdown,
+    worksheet: stubWorksheet,
+    hardFilters: stubWorksheet.hardFilters,
+    sanctions: undefined,
+    scoreBreakdown: undefined,
+    economics: undefined,
+  };
+}
+
+const PARITY_COLS = [
+  'cargo_id',
+  'vessel_id',
+  'cargo_item_index',
+  'vessel_item_index',
+  'score',
+  'reason',
+  'status',
+  'cargo_type',
+  'load_port',
+  'discharge_port',
+  'laycan_start',
+  'laycan_end',
+  'vessel_dwt',
+  'fit_percent',
+  'fit_breakdown',
+  'worksheet_json',
