+beforeEach(() => {
+  jest.clearAllMocks();
+});
+
+describe('write-path parity — computeAndPersistMatches vs persistSessionMatches', () => {
+  it('both paths write the same 21 columns for an identical cargo×vessel pair', async () => {
+    const cargo = makeCargo();
+    const vessel = makeVessel();
+    const match = makeMatchObject();
