+    // Path A: background precompute
+    const dbA = freshDb();
+    (analyzePairs as jest.Mock).mockResolvedValueOnce({
+      matches: [match],
+      lowConfidenceMatches: [],
+      insufficientData: [],
+      blockedMatches: [],
+    });
+    await computeAndPersistMatches([cargo], [vessel], 'session-A', dbA);
+    const [rowA] = listMatches(dbA, { sortBy: 'score', sortDir: 'desc' });
+    expect(rowA).toBeDefined();
+
+    // Path B: live session persist
+    const dbB = freshDb();
+    persistSessionMatches(dbB, 'session-B', [match], [cargo], [vessel]);
+    const [rowB] = listMatches(dbB, { sortBy: 'score', sortDir: 'desc' });
+    expect(rowB).toBeDefined();
+
+    // Both paths must write the same values for each parity column.
+    for (const col of PARITY_COLS) {
+      expect({ col, val: rowA[col] }).toEqual({ col, val: rowB[col] });
+    }
+
+    // Both paths must write fit_breakdown as non-null parseable JSON.
+    expect(rowA.fit_breakdown).not.toBeNull();
+    expect(rowB.fit_breakdown).not.toBeNull();
+    const fbA = JSON.parse(rowA.fit_breakdown!);
+    const fbB = JSON.parse(rowB.fit_breakdown!);
+    expect(fbA.fitPercent).toBeDefined();
+    expect(fbA.components).toHaveLength(10);
+    expect(fbB.fitPercent).toBe(fbA.fitPercent);
+
+    // worksheet_json must be non-null on both paths.
+    expect(rowA.worksheet_json).not.toBeNull();
+    expect(rowB.worksheet_json).not.toBeNull();
+
+    // breakeven_tce_usd_per_day and ballast_distance_nm should be non-null on both.
+    expect(rowA.breakeven_tce_usd_per_day).not.toBeNull();
+    expect(rowB.breakeven_tce_usd_per_day).not.toBeNull();
+
+    // Item indices must match cargo/vessel emailId structure.
+    expect(rowA.cargo_item_index).toBe(0);
+    expect(rowB.cargo_item_index).toBe(0);
+    expect(rowA.vessel_item_index).toBe(0);
+    expect(rowB.vessel_item_index).toBe(0);
+  });
+});
