+/**
+ * B.2 Parity test — computeAndPersistMatches vs persistSessionMatches write-path convergence.
+ *
+ * Both paths must write the same 21 columns for a given cargo×vessel pair so a
+ * match renders identically regardless of which writer saved it.
+ *
+ * 21 columns under test:
+ *   cargo_id, vessel_id, cargo_item_index, vessel_item_index,
+ *   score, reason, status, user_id,
+ *   cargo_type, load_port, discharge_port, laycan_start, laycan_end, vessel_dwt,
+ *   tce_usd_per_day, distance_nm, freight_rate_usd_per_mt, freight_rate_source,
+ *   fit_percent, fit_breakdown, worksheet_json
+ *
+ * Economics / breakeven / ballast are also spot-checked (both paths write them).
+ *
+ * analyzePairs is mocked with a realistic Match object (fitBreakdown + worksheet) so
+ * the test is deterministic and LLM-free.
+ */
+
+import Database from 'better-sqlite3';
+import migration032 from '@/lib/migrations/032-matches';
+import migration033 from '@/lib/migrations/033-matches-score-breakdown';
+import migration034 from '@/lib/migrations/034-matches-unique-constraint';
+import migration035 from '@/lib/migrations/035-matches-tce-distance';
+import migration036 from '@/lib/migrations/036-matches-freight-rate';
+import migration041 from '@/lib/migrations/041-matches-vessel-name';
+import migration042 from '@/lib/migrations/042-matches-fit';
+import migration044 from '@/lib/migrations/044-matches-item-index';
+import migration045 from '@/lib/migrations/045-matches-worksheet';
+import migration046 from '@/lib/migrations/046-matches-consumption-estimated';
+import migration047 from '@/lib/migrations/047-matches-ballast-distance';
+import migration050 from '@/lib/migrations/050-matches-breakeven';
+import { computeAndPersistMatches } from '@/lib/matching/compute-matches';
+import { persistSessionMatches } from '@/lib/matching/persist-session-matches';
+import { listMatches } from '@/lib/matching/matches-repository';
+import type { ParsedCargo, ParsedVessel, FitBreakdown } from '@/lib/types';
+
+jest.mock('@/lib/matching/pair-analyzer', () => ({
+  analyzePairs: jest.fn(),
+}));
+
+import { analyzePairs } from '@/lib/matching/pair-analyzer';
+
+function freshDb(): Database.Database {
+  const db = new Database(':memory:');
+  migration032.up(db);
+  migration033.up(db);
+  migration034.up(db);
+  migration035.up(db);
+  migration036.up(db);
+  migration041.up(db);
+  migration042.up(db);
+  migration044.up(db);
+  migration045.up(db);
+  migration046.up(db);
+  migration047.up(db);
+  migration050.up(db);
+  return db;
+}
+
+const CARGO_ID = 'cargo@demo.local';
+const VESSEL_ID = 'vessel@demo.local';
+
+function makeCargo(overrides: Partial<ParsedCargo> = {}): ParsedCargo {
+  return {
+    emailId: CARGO_ID,
+    itemIndex: 0,
+    originPort: { value: 'Rotterdam', confidence: 'confirmed' },
+    destinationPort: { value: 'Singapore', confidence: 'confirmed' },
+    cargoType: 'grain',
+    laycan: '1-15 Jul 2026',
+    cargoDescription: { value: 'Wheat 25kt', confidence: 'confirmed' },
+    weightMt: { value: 25000, confidence: 'confirmed' },
+    weightMtMin: 24000,
+    weightMtMax: 26000,
+    volumeCbm: null,
+    dimensions: null,
+    containerType: null,
+    quantity: null,
+    incoterms: null,
+    preferredDates: null,
+    loadingRate: null,
+    dischargeRate: null,
+    commissionPercent: null,
+    commissionTerms: null,
+    specialRequirements: null,
+    stowageFactor: null,
+    missingInfo: [],
+    originCountry: null,
+    destinationCountry: null,
+    ...overrides,
+  };
+}
+
+function makeVessel(overrides: Partial<ParsedVessel> = {}): ParsedVessel {
+  return {
+    emailId: VESSEL_ID,
+    itemIndex: 0,
+    dwtSummer: { value: 32000, confidence: 'confirmed' },
+    vesselName: { value: 'M/V DEMO', confidence: 'confirmed' },
+    imo: null,
+    flag: null,
+    built: null,
+    classSociety: null,
+    pandi: null,
+    dwcc: null,
+    draftMax: null,
+    loa: null,
+    beam: null,
+    grt: null,
+    nrt: null,
+    holdsCount: null,
+    hatchesCount: null,
+    grainCapacity: null,
+    grainCapacityUnit: null,
+    baleCapacity: null,
+    holdDimensions: null,
+    hatchDimensions: null,
+    tankTopStrength: null,
+    geared: null,
+    craneCapacity: null,
+    hatchType: null,
+    vesselType: null,
+    openPosition: { value: 'Antwerp', confidence: 'confirmed' },
+    openDate: { value: '2026-06-28', confidence: 'confirmed' },
+    direction: null,
+    restrictions: [],
+    lastCargoes: null,
+    speedLaden: 13,
+    speedBallast: null,
+    consumption: 28,
+    deckCapacity: null,
+    specialFeatures: [],
+    ...overrides,
+  };
+}
+
+const stubFitBreakdown: FitBreakdown = {
+  components: [
+    { factor: 'utilisation', label: 'Utilisation', weight: 19, score: 16, rationale: 'Good util' },
+    { factor: 'timing', label: 'Timing', weight: 15, score: 13, rationale: 'Tight' },
+    { factor: 'ballast', label: 'Ballast', weight: 15, score: 10, rationale: 'Medium' },
+    { factor: 'classFit', label: 'Class fit', weight: 9, score: 9, rationale: 'Perfect' },
+    { factor: 'cargoType', label: 'Cargo type', weight: 6, score: 6, rationale: 'Grain ok' },
+    { factor: 'cranes', label: 'Cranes', weight: 6, score: 6, rationale: 'N/A' },
+    { factor: 'volume', label: 'Volume', weight: 3, score: 3, rationale: 'ok' },
+    { factor: 'draft', label: 'Draft', weight: 2, score: 2, rationale: 'ok' },
+    { factor: 'vetting', label: 'Vetting', weight: 7, score: 6, rationale: 'ok' },
+    { factor: 'economics', label: 'Economics', weight: 18, score: 14, rationale: 'ok' },
+  ],
+  totalWeight: 100,
+  fitPercent: 85,
+  partCargo: false,
+  vesselClass: 'handysize',
+  sanctionsPenalty: 0,
+  appliedCap: null,
+  inputs: {
+    distanceNm: 8500,
+    gapDays: 3,
+    verdict: 'tight',
+    utilisation: 0.78,
+    vesselDwt: 32000,
+    cargoWtMax: 25000,
+  },
+};
+
+const stubWorksheet = {
+  readiness: {
+    verdict: 'tight' as const,
+    gapDays: 3,
+    laycanStart: '2026-07-01',
+    laycanEnd: '2026-07-15',
+    openDate: '2026-06-28',
+    openPosition: 'Antwerp',
+    distanceNm: 200,
+    distanceExact: true,
+    speedKn: 13,
+    sailingDays: 1,
+    arrivalDate: '2026-06-29',
+    explanation: 'Arrives 2 days before laycan open',
+  },
+  vessel: {
+    draftMax: null,
+    grainCapacity: null,
+    grainCapacityUnit: null,
+    geared: null,
+    vesselType: null,
+    flag: null,
+    built: null,
+    pandi: null,
+    classSociety: null,
+    lastCargoes: null,
+    dwtSummer: 32000,
+    dwcc: null,
+  },
+  cargo: { weightMt: 25000, weightMtEffective: 25000, cargoType: 'grain', loadPort: 'Rotterdam', dischargePort: 'Singapore' },
+  hardFilters: { draft: { pass: true }, crane: { pass: true }, volume: { pass: true }, destDraft: { pass: true } },
+  sanctions: undefined,
+};
+
+function makeMatchObject() {
+  return {
+    cargoEmailId: CARGO_ID,
+    cargoItemIndex: 0,
+    vesselEmailId: VESSEL_ID,
+    vesselItemIndex: 0,
+    score: 82,
+    matchLevel: 'good' as const,
+    matchReasons: ['Good timing and fit'],
+    issues: [],
+    fitPercent: 85,
+    fitBreakdown: stubFitBreakdown,
+    worksheet: stubWorksheet,
+    hardFilters: stubWorksheet.hardFilters,
+    sanctions: undefined,
+    scoreBreakdown: undefined,
+    economics: undefined,
+  };
+}
+
+const PARITY_COLS = [
+  'cargo_id',
+  'vessel_id',
+  'cargo_item_index',
+  'vessel_item_index',
+  'score',
+  'reason',
+  'status',
+  'cargo_type',
+  'load_port',
+  'discharge_port',
+  'laycan_start',
+  'laycan_end',
+  'vessel_dwt',
+  'fit_percent',
+  'fit_breakdown',
+  'worksheet_json',
+] as const;
+
+beforeEach(() => {
+  jest.clearAllMocks();
+});
+
+describe('write-path parity — computeAndPersistMatches vs persistSessionMatches', () => {
+  it('both paths write the same 21 columns for an identical cargo×vessel pair', async () => {
+    const cargo = makeCargo();
+    const vessel = makeVessel();
+    const match = makeMatchObject();
+
+    // Path A: background precompute
+    const dbA = freshDb();
+    (analyzePairs as jest.Mock).mockResolvedValueOnce({
+      matches: [match],
+      lowConfidenceMatches: [],
+      insufficientData: [],
+      blockedMatches: [],
+    });
+    await computeAndPersistMatches([cargo], [vessel], 'session-A', dbA);
+    const [rowA] = listMatches(dbA, { sortBy: 'score', sortDir: 'desc' });
+    expect(rowA).toBeDefined();
+
+    // Path B: live session persist
+    const dbB = freshDb();
+    persistSessionMatches(dbB, 'session-B', [match], [cargo], [vessel]);
+    const [rowB] = listMatches(dbB, { sortBy: 'score', sortDir: 'desc' });
+    expect(rowB).toBeDefined();
+
+    // Both paths must write the same values for each parity column.
+    for (const col of PARITY_COLS) {
+      expect({ col, val: rowA[col] }).toEqual({ col, val: rowB[col] });
+    }
+
+    // Both paths must write fit_breakdown as non-null parseable JSON.
+    expect(rowA.fit_breakdown).not.toBeNull();
+    expect(rowB.fit_breakdown).not.toBeNull();
